export function getStaticPost(slug: string, language: string): StaticBlogPost | undefined {
  return STATIC_BLOG_POSTS.find(p => p.slug === slug && p.language === language)
    || STATIC_BLOG_POSTS.find(p => p.slug === slug && p.language === "en");
}

export function getAllStaticPosts(language?: string): StaticBlogPost[] {
  if (!language) return STATIC_BLOG_POSTS;
  return STATIC_BLOG_POSTS.filter(p => p.language === language);
}
